cd /root && python3 -c "
import random, string

def rand_line(n):
    return ''.join(random.choice(string.ascii_letters + string.digits + '!@#\$%^&*()_+-=<>~|;:\",./?') for _ in range(n))

lines = []
for i in range(50):
    if random.random() < 0.3:
        lines.append('')
    else:
        lines.append(rand_line(random.randint(5, 80)))

with open('system_logs.txt', 'w') as f:
    f.write('\n'.join(lines) + '\n')
print('file initialized with', len(lines), 'lines')
"
